def load_data(path, n_instances=0):
    data = []
    with open(path) as f:
        for line in f:
            if line.strip():
                data.append(json.loads(line))
                if 0 < n_instances <= len(data):
                    break
    return data


def parse_extraction(text):
    """Parse JSON extraction from model output. Returns dict with 'entities' key."""
    text = text.strip()
    if text.startswith("```json"):
        text = text[7:]
    if text.startswith("```"):
        text = text[3:]
    if text.endswith("```"):
        text = text[:-3]
    text = text.strip()

    try:
        obj = json.loads(text)
        if isinstance(obj, dict):
            entities = obj.get("entities", [])
            valid = []
            for e in entities:
                if isinstance(e, dict) and "text" in e and "type" in e:
                    if "start" in e and "end" in e:
                        valid.append({
                            "text": e["text"],
                            "type": e["type"].lower(),
                            "start": int(e["start"]),
                            "end": int(e["end"]),
                        })
            return {"entities": valid, "relations": [], "events": []}
    except (json.JSONDecodeError, ValueError):
        pass

    return {"entities": [], "relations": [], "events": []}


